const string Dir="Assets/Scenes/Oasis/CityBuildingSigns",ScenePath="Assets/Editor/DayNightBackups/Gangstar Final Env.unity",Group="City Building Signs - Shared Atlas";
static BindingFlags Flags=BindingFlags.Static|BindingFlags.NonPublic;
class Geo{public MeshRenderer r;public Vector3[] p;public int[] ids;public Bounds bounds;}
class Site{public Geo g;public Vector3 p,n;public float w,h;public int art;public string kind;}
static V Field<V>(object o,string n)=>(V)o.GetType().GetField(n).GetValue(o);
static Geo Read(MeshRenderer r){var f=r.GetComponent<MeshFilter>();var d=typeof(FinalPNGCityDetails).GetMethod("Read",Flags).Invoke(null,new object[]{f.sharedMesh});return new Geo{r=r,p=Field<Vector3[]>(d,"p").Select(f.transform.TransformPoint).ToArray(),ids=Field<int[]>(d,"ids"),bounds=r.bounds};}
static bool Hit(Geo g,Vector3 origin,Vector3 dir,out Vector3 hit,out Vector3 normal){float best=10000;hit=normal=Vector3.zero;for(int i=0;i<g.ids.Length;i+=3){var a=g.p[g.ids[i]];var b=g.p[g.ids[i+1]]-a;var c=g.p[g.ids[i+2]]-a;var q=Vector3.Cross(dir,c);float det=Vector3.Dot(b,q);if(Mathf.Abs(det)<.000001f)continue;var s=origin-a;float u=Vector3.Dot(s,q)/det;if(u<0||u>1)continue;var v=Vector3.Cross(s,b);float t=Vector3.Dot(dir,v)/det;if(t<0||u+t>1)continue;float distance=Vector3.Dot(c,v)/det;if(distance<.001f||distance>=best)continue;best=distance;hit=origin+dir*distance;normal=Vector3.Cross(b,c).normalized;}return best<10000;}
static bool Fits(Geo g,Vector3 p,Vector3 n,float w,float h){var right=Vector3.Cross(Vector3.up,n);foreach(float x in new[]{-.5f,0,.5f})foreach(float y in new[]{-.5f,0,.5f}){var q=p+right*x*w+Vector3.up*y*h;if(!Hit(g,q+n*2,-n,out var hit,out var normal)||Mathf.Abs(Vector3.Dot(hit-p,n))>.14f||Mathf.Abs(Vector3.Dot(normal,n))<.975f)return false;}return true;}
static bool Clear(Site s,Geo[] all,Vector3[] roads){if(all.Any(g=>g!=s.g&&g.bounds.Contains(s.p+s.n*.5f)))return false;foreach(var road in roads.Where(p=>Vector3.Dot(p-s.p,s.n)>3&&new Vector2(p.x-s.p.x,p.z-s.p.z).magnitude<130).OrderBy(p=>(p-s.p).sqrMagnitude).Take(12)){var p=new Vector3(road.x,31.2f,road.z);var dir=(s.p-p).normalized;float distance=Vector3.Distance(p,s.p);bool blocked=false;foreach(var g in all){if(g.bounds.IntersectRay(new Ray(p,dir),out float near)&&near<distance-.35f&&Hit(g,p,dir,out var hit,out var nn)&&Vector3.Distance(p,hit)<distance-.35f){blocked=true;break;}}if(!blocked)return true;}return false;}
static Vector3[] Directions(Geo g,Vector3[] roads){var aim=roads.OrderBy(p=>new Vector2(p.x-g.bounds.center.x,p.z-g.bounds.center.z).sqrMagnitude).First()-g.bounds.center;aim.y=0;var found=new List<Vector3>{Vector3.forward,Vector3.back,Vector3.left,Vector3.right};for(int i=0;i<g.ids.Length;i+=3){var a=g.p[g.ids[i]];var b=g.p[g.ids[i+1]];var c=g.p[g.ids[i+2]];var cross=Vector3.Cross(b-a,c-a);if(cross.magnitude<4||Mathf.Abs(cross.normalized.y)>.08f)continue;var n=cross.normalized;if(Vector3.Dot((a+b+c)/3-g.bounds.center,n)<0)n=-n;n.y=0;n.Normalize();if(!found.Any(v=>Vector3.Dot(v,n)>.99))found.Add(n);}return found.OrderByDescending(n=>Vector3.Dot(n,aim.normalized)).ToArray();}
static Site Wall(Geo g,Vector3[] directions,float w,float h,string kind,int art,Geo[] all,Vector3[] roads,Site previous=null){foreach(var n in directions){var right=Vector3.Cross(Vector3.up,n);float span=Mathf.Abs(n.x)*g.bounds.size.z+Mathf.Abs(n.z)*g.bounds.size.x;float width=Mathf.Min(w,span*.72f),height=kind=="Wide"?width/1.8f:h;if(width<1||height>g.bounds.size.y*.60f)continue;
foreach(float level in new[]{.32f,.52f,.72f,.20f})foreach(float offset in new[]{0f,-.25f,.25f}){var target=g.bounds.center+right*span*offset;target.y=g.bounds.min.y+Mathf.Clamp(g.bounds.size.y*level,4+height*.5f,g.bounds.size.y-height*.5f-.5f);if(!Hit(g,target+n*400,-n,out var p,out var normal)||Mathf.Abs(Vector3.Dot(normal,n))<.975f)continue;var s=new Site{g=g,p=p+n*.13f,n=n,w=width,h=height,kind=kind,art=art};if(previous!=null&&(Mathf.Abs(Vector3.Dot(p-previous.p,previous.n))<.3f&&(Mathf.Abs(Vector3.Dot(p-previous.p,right))<(width+previous.w)*.5f+.5f&&Mathf.Abs(p.y-previous.p.y)<(height+previous.h)*.5f+.5f)))continue;if(!Fits(g,p,n,width+.3f,height+.3f)||!Clear(s,all,roads))continue;return s;}}return null;}
static Vector4 Rect(int tile){if(tile<12){int row=tile/4,col=tile%4;float y=(row==0?24:row==1?230:438)/1254f;float end=(row==0?190:row==1?404:608)/1254f;return new Vector4((col*313.5f+9)/1254f,1-end,(313.5f-18)/1254f,end-y);}if(tile<20){int col=tile-12;return new Vector4((col*156.75f+10)/1254f,1-973/1254f,(156.75f-20)/1254f,(973-635)/1254f);}return new Vector4(((tile-20)*313.5f+9)/1254f,1-1243/1254f,(313.5f-18)/1254f,(1243-990)/1254f);}
class B{public List<Vector3> p=new List<Vector3>(),n=new List<Vector3>();public List<Vector2> uv=new List<Vector2>();public List<Color> c=new List<Color>();public List<int> ids=new List<int>();
public void Q(Vector3 a,Vector3 b,Vector3 d,Vector3 e,Vector4 rect,Color color){int i=p.Count;p.AddRange(new[]{a,b,d,e});var nn=Vector3.Cross(b-a,d-a).normalized;n.AddRange(Enumerable.Repeat(nn,4));uv.AddRange(new[]{new Vector2(rect.x,rect.y),new Vector2(rect.x+rect.z,rect.y),new Vector2(rect.x+rect.z,rect.y+rect.w),new Vector2(rect.x,rect.y+rect.w)});c.AddRange(Enumerable.Repeat(color,4));ids.AddRange(new[]{i,i+1,i+2,i,i+2,i+3});}
public void Box(Vector3 center,Vector3 right,Vector3 up,Vector3 normal,float w,float h,float depth,Color color){var r=right*w*.5f;var u=up*h*.5f;var n=normal*depth*.5f;var z=Vector4.zero;Q(center-r-u+n,center+r-u+n,center+r+u+n,center-r+u+n,z,color);Q(center+r-u-n,center-r-u-n,center-r+u-n,center+r+u-n,z,color);Q(center-r-u-n,center-r-u+n,center-r+u+n,center-r+u-n,z,color);Q(center+r-u+n,center+r-u-n,center+r+u-n,center+r+u+n,z,color);Q(center-r+u+n,center+r+u+n,center+r+u-n,center-r+u-n,z,color);Q(center-r-u-n,center+r-u-n,center+r-u+n,center-r-u+n,z,color);}
public void Board(Site s,bool two=false){var right=Vector3.Cross(Vector3.up,s.n);Box(s.p-s.n*.10f,right,Vector3.up,s.n,s.w+.16f,s.h+.16f,.18f,new Color(.035f,.039f,.043f,0));Q(s.p-right*s.w*.5f-Vector3.up*s.h*.5f,s.p+right*s.w*.5f-Vector3.up*s.h*.5f,s.p+right*s.w*.5f+Vector3.up*s.h*.5f,s.p-right*s.w*.5f+Vector3.up*s.h*.5f,Rect(s.art),new Color(1,1,1,.5f));if(two){var back=s.p-s.n*.21f;Q(back+right*s.w*.5f-Vector3.up*s.h*.5f,back-right*s.w*.5f-Vector3.up*s.h*.5f,back-right*s.w*.5f+Vector3.up*s.h*.5f,back+right*s.w*.5f+Vector3.up*s.h*.5f,Rect(s.art),new Color(1,1,1,.5f));}}
public Mesh Mesh(string name,Vector3 origin){var m=new Mesh{name=name,indexFormat=IndexFormat.UInt32};m.SetVertices(p.Select(v=>v-origin).ToList());m.SetNormals(n);m.SetUVs(0,uv);m.SetColors(c);m.SetTriangles(ids,0);m.RecalculateBounds();return m;}}
static Color[] Palette={new Color(.12f,.68f,.9f,1),new Color(1,.59f,.15f,1),new Color(.8f,.12f,.52f,1),new Color(.32f,.82f,.32f,1)};
static void Neon(B mesh,Geo g,Vector3[] directions,int index){var color=Palette[index%Palette.Length];foreach(var n in directions.Take(2)){float span=Mathf.Abs(n.x)*g.bounds.size.z+Mathf.Abs(n.z)*g.bounds.size.x;var right=Vector3.Cross(Vector3.up,n);var target=g.bounds.center;target.y=g.bounds.max.y-.7f;if(!Hit(g,target+n*400,-n,out var p,out var normal)||Mathf.Abs(Vector3.Dot(normal,n))<.975f)continue;float width=Mathf.Min(span*.82f,35);if(Fits(g,p,n,width,.14f)){mesh.Box(p+n*.19f,right,Vector3.up,n,width,.095f,.055f,color);return;}}}
static FinalCitySigns(){EditorApplication.update+=Poll;}
static void Poll(){if(!File.Exists("FinalCitySigns.request")||EditorApplication.isCompiling||EditorApplication.isPlayingOrWillChangePlaymode)return;File.Delete("FinalCitySigns.request");Run();}
static void Photo(Scene s,Vector3 p,Vector3 target,string name)=>typeof(FinalPNGCityDetails).GetMethod("Capture",Flags).Invoke(null,new object[]{s,p,target,name});
static void Run(){var log=new StringBuilder();GameObject group=null;try{var scene=SceneManager.GetSceneByPath(ScenePath);if(!scene.isLoaded)throw new Exception("Target scene not loaded");if(scene.GetRootGameObjects().Any(g=>g.name==Group))throw new Exception("City sign prefab already installed; refusing duplicate build");string backup="FinalEnvironmentRoadBackup/CitySigns-"+DateTime.UtcNow.ToString("yyyyMMdd-HHmmss");Directory.CreateDirectory(backup);EditorSceneManager.SaveScene(scene,backup+"/Before.unity",true);
var native=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshRenderer>(true)).Where(r=>r.enabled&&r.gameObject.activeInHierarchy&&r.sharedMaterials.Any(m=>m&&m.name.StartsWith("Building"))&&r.GetComponent<MeshFilter>()&&r.bounds.size.y>7&&r.bounds.size.y<180&&r.bounds.size.x>5&&r.bounds.size.z>5&&r.bounds.size.x<180&&r.bounds.size.z<180).ToArray();var all=native.Select(Read).ToArray();var controller=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<CityDayNightController>(true)).First();var roads=controller.streetLightPositions;if(roads==null||roads.Length==0)throw new Exception("Roadside points missing");int lights=scene.GetRootGameObjects().Sum(g=>g.GetComponentsInChildren<Light>(true).Length);
var importer=(TextureImporter)AssetImporter.GetAtPath(Dir+"/City Signs Atlas.png");importer.wrapMode=TextureWrapMode.Clamp;importer.mipmapEnabled=true;importer.filterMode=FilterMode.Trilinear;importer.anisoLevel=4;importer.npotScale=TextureImporterNPOTScale.None;importer.maxTextureSize=2048;importer.isReadable=false;foreach(string platform in new[]{"Android","iPhone"})importer.SetPlatformTextureSettings(new TextureImporterPlatformSettings{name=platform,overridden=true,maxTextureSize=2048,format=TextureImporterFormat.ASTC_4x4,compressionQuality=100});importer.SaveAndReimport();var shader=Shader.Find("City/Mobile Shared Sign Atlas");if(!shader)throw new Exception("Shared shader missing");var mat=new Material(shader){name="City Shared Sign Atlas",enableInstancing=true};mat.SetTexture("_Atlas",AssetDatabase.LoadAssetAtPath<Texture2D>(Dir+"/City Signs Atlas.png"));AssetDatabase.CreateAsset(mat,Dir+"/City Shared Sign Atlas.mat");
group=new GameObject(Group);var placements=new List<Site>();var rows=new List<string>{"building,wideArt,verticalArt,logo,triangles"};int count=0,wide=0,vertical=0,roof=0,skipped=0,triangles=0;int[] used=new int[24];var gen=new System.Random(12824);
foreach(var g in all.OrderBy(v=>v.bounds.center.x).ThenBy(v=>v.bounds.center.z)){var dirs=Directions(g,roads);var b=new B();int seed=count+skipped;int art=seed%12;var close=placements.Where(s=>s.kind=="Wide"&&new Vector2(s.p.x-g.bounds.center.x,s.p.z-g.bounds.center.z).magnitude<80).Select(s=>s.art).ToArray();for(int j=0;j<12&&close.Contains(art);j++)art=(art+1)%12;float width=Mathf.Clamp(Mathf.Max(g.bounds.size.x,g.bounds.size.z)*.40f,5.5f,18);var main=Wall(g,dirs,width,width/1.8f,"Wide",art,all,roads);if(main==null)main=Wall(g,dirs,Mathf.Min(width,7),3.5f,"Wide",art,all,roads);
if(main!=null){b.Board(main);placements.Add(main);used[art]++;wide++;}
int bladeArt=12+seed%8;var blade=Wall(g,dirs,1.55f,Mathf.Clamp(g.bounds.size.y*.24f,3.5f,7),"Vertical",bladeArt,all,roads,main);if(blade!=null){var right=Vector3.Cross(Vector3.up,blade.n);blade.p+=blade.n*1.2f;var mount=blade.p-blade.n*.55f;b.Box(mount,blade.n,Vector3.up,right,1.1f,.12f,.12f,new Color(.045f,.045f,.05f,0));b.Box(mount+Vector3.up*(blade.h*.32f),blade.n,Vector3.up,right,1.1f,.12f,.12f,new Color(.045f,.045f,.05f,0));blade.n=right;b.Board(blade,true);placements.Add(blade);used[bladeArt]++;vertical++;}
int logo=-1;if(seed%5==0||main==null&&blade==null){var n=dirs[0];var right=Vector3.Cross(Vector3.up,n);var target=g.bounds.center+n*Mathf.Min(g.bounds.extents.x,g.bounds.extents.z)*.45f;if(Hit(g,new Vector3(target.x,g.bounds.max.y+10,target.z),Vector3.down,out var floor,out var norm)&&Mathf.Abs(norm.y)>.9f&&floor.y>g.bounds.max.y-4){float size=Mathf.Clamp(Mathf.Min(g.bounds.size.x,g.bounds.size.z)*.13f,2.3f,4.2f);var s=new Site{g=g,p=floor+Vector3.up*(size*.5f+1),n=n,w=size,h=size,art=20+seed%4,kind="Roof"};if(Clear(s,all,roads)){b.Board(s,true);foreach(float x in new[]{-.3f,.3f})b.Box(floor+right*x*size+Vector3.up*.55f,right,Vector3.up,n,.10f,1.1f,.10f,new Color(.04f,.045f,.05f,0));placements.Add(s);used[s.art]++;roof++;logo=s.art;}}}
if(b.p.Count==0){skipped++;log.AppendLine("SKIPPED no clear supported facade: "+g.r.name+" "+g.bounds.center);continue;}if(seed%3!=1)Neon(b,g,dirs,seed);
string name="Signs "+count.ToString("000")+" - "+g.r.name;var go=new GameObject(name);go.transform.SetParent(group.transform,false);go.transform.position=g.bounds.center;var mesh=b.Mesh(name,g.bounds.center);AssetDatabase.CreateAsset(mesh,Dir+"/Meshes/Signs-"+count.ToString("000")+".asset");go.AddComponent<MeshFilter>().sharedMesh=mesh;var r=go.AddComponent<MeshRenderer>();r.sharedMaterial=mat;r.shadowCastingMode=ShadowCastingMode.Off;r.receiveShadows=false;r.lightProbeUsage=LightProbeUsage.Off;r.reflectionProbeUsage=ReflectionProbeUsage.Off;
GameObjectUtility.SetStaticEditorFlags(go,StaticEditorFlags.BatchingStatic|StaticEditorFlags.OccludeeStatic);var lod=go.AddComponent<LODGroup>();lod.fadeMode=LODFadeMode.None;lod.SetLODs(new[]{new LOD(.045f,new Renderer[]{r})});lod.RecalculateBounds();lod.size=Mathf.Clamp(lod.size,8,24);PrefabUtility.SaveAsPrefabAssetAndConnect(go,Dir+"/Prefabs/Building Signs "+count.ToString("000")+".prefab",InteractionMode.AutomatedAction);triangles+=mesh.triangles.Length/3;rows.Add(g.r.name.Replace(","," ") +","+ (main!=null?art:-1)+","+(blade!=null?bladeArt:-1)+","+logo+","+mesh.triangles.Length/3);count++;if(count%25==0){File.WriteAllText("FinalEnvironmentRoadReview/CitySignsProgress.txt","Buildings completed="+count+" of "+all.Length+"; skipped="+skipped);}}
if(count<100)throw new Exception("Unexpected low city coverage="+count);var old=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).FirstOrDefault(t=>t.name=="Building Billboards - Sparse");if(old)old.gameObject.SetActive(false);AssetDatabase.SaveAssets();PrefabUtility.SaveAsPrefabAssetAndConnect(group,Dir+"/City Building Signs.prefab",InteractionMode.AutomatedAction);EditorSceneManager.MarkSceneDirty(scene);if(!EditorSceneManager.SaveScene(scene))throw new Exception("Scene save failed");if(lights!=scene.GetRootGameObjects().Sum(g=>g.GetComponentsInChildren<Light>(true).Length))throw new Exception("Light count changed");
File.WriteAllLines("FinalEnvironmentRoadReview/CitySignsPlacements.csv",rows);log.AppendLine("SUCCESS eligible buildings="+all.Length+"; signed building prefabs="+count+"; skipped="+skipped+"; wide posters="+wide+"; vertical signs="+vertical+"; roof logos="+roof+"; triangles="+triangles+"; one PNG atlas, one shared material; no new lights/colliders; per-building combined meshes, static batching and distance LOD culling; old seven sparse billboards hidden; scene and master prefab saved; backup="+backup);for(int i=0;i<24;i++)log.AppendLine("Atlas tile "+i+" used "+used[i]+" times");
File.WriteAllText("FinalEnvironmentRoadReview/CitySignsReport.txt",log.ToString());bool night=controller.IsNight;try{var chosen=new List<Site>();foreach(var target in new[]{new Vector3(230,40,-40),new Vector3(-120,40,-250),new Vector3(540,40,160),new Vector3(430,40,-320)}){var s=placements.Where(s=>s.kind=="Wide"&&!chosen.Contains(s)).OrderBy(s=>(s.p-target).sqrMagnitude).First();chosen.Add(s);int i=chosen.Count;controller.ApplyDay();Photo(scene,s.p+s.n*Mathf.Max(28,s.w*2.3f)+Vector3.up*4,s.p,"City-Signs-Day-"+i);controller.ApplyNight();Photo(scene,s.p+s.n*Mathf.Max(28,s.w*2.3f)+Vector3.up*4,s.p,"City-Signs-Night-"+i);}}finally{if(night)controller.ApplyNight();else controller.ApplyDay();}int errors=ShaderUtil.GetShaderMessages(shader).Count(v=>v.severity.ToString()=="Error");if(errors>0)throw new Exception("Shader errors="+errors);log.AppendLine("Rendered four district previews in day/night; shader errors=0; original building mesh/material references unchanged; phone FPS not measured");EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);
}catch(Exception e){log.AppendLine("FAILED "+e);Debug.LogException(e);}File.WriteAllText("FinalEnvironmentRoadReview/CitySignsReport.txt",log.ToString());}}
